var L_vocabulary_store_js=globalThis.I18n||{t:(s,v)=>v?s.replace(/\{(\w+)\}/g,(m,k)=>v[k]??m):s,error:s=>s,locale:undefined};
/* User vocabulary is separate from replaceable dictionaries and model caches. */
(function(root){
 const icons=['📘','📗','📕','📙','📓','🗂️'],languages=['ko','ja','en'];let pending;
 const normalize=s=>String(s).normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ');
 const dedupe=r=>JSON.stringify([r.notebook,normalize(r.word),r.sourceLang,r.targetLang,normalize(r.meaning)]);
 const text=(v,max,empty=false)=>typeof v==='string'&&v.length<=max&&(empty||!!v.trim());
 function validBook(b){return b&&text(b.id,100)&&text(b.name,80)&&icons.includes(b.icon)}
 function valid(r){return r&&text(r.id,100)&&text(r.notebook,100)&&text(r.word,500)&&text(r.meaning,12000)&&text(r.reading,300,true)&&languages.includes(r.sourceLang)&&languages.includes(r.targetLang)&&(!r.provenance||(text(r.provenance.label,500)&&text(r.provenance.url,2048)&&/^https:\/\//.test(r.provenance.url)&&text(r.provenance.license,100)&&text(r.provenance.version,64)&&text(r.provenance.originalWord,500)&&text(r.provenance.originalMeaning,200000)))}
 function db(){if(!pending)pending=new Promise((resolve,reject)=>{const q=indexedDB.open('aka-vocabulary',1);q.onupgradeneeded=()=>{const d=q.result;d.createObjectStore('books',{keyPath:'id'});const s=d.createObjectStore('entries',{keyPath:'id'});s.createIndex('notebook','notebook');s.createIndex('dedupe','dedupe',{unique:true})};q.onsuccess=()=>{q.result.onversionchange=()=>{q.result.close();pending=null};resolve(q.result)};q.onerror=()=>{pending=null;reject(q.error)};q.onblocked=()=>{pending=null;reject(Error(L_vocabulary_store_js.t("다른 앱 창을 닫고 다시 시도하세요.")))}});return pending}
 async function transaction(stores,mode,fn){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction(stores,mode);let value,error;fn(t,v=>value=v,message=>{error=Error(message);t.abort()});t.oncomplete=()=>resolve(value);t.onerror=e=>{error=error||e.target.error};t.onabort=()=>reject((error?.name==='ConstraintError'||t.error?.name==='ConstraintError')?Error(L_vocabulary_store_js.t("같은 단어와 뜻이 이미 저장돼 있습니다.")):error||t.error||Error(L_vocabulary_store_js.t("단어장을 저장하지 못했습니다. 저장 공간을 확인하세요.")))})}
 const books=()=>transaction(['books'],'readonly',(t,set)=>{const r=t.objectStore('books').getAll();r.onsuccess=()=>set(r.result.sort((a,b)=>a.createdAt-b.createdAt||a.id.localeCompare(b.id)))});
 const entries=notebook=>transaction(['entries'],'readonly',(t,set)=>{const r=t.objectStore('entries').index('notebook').getAll(notebook);r.onsuccess=()=>set(r.result.sort((a,b)=>b.createdAt-a.createdAt||a.id.localeCompare(b.id)))});
 async function saveBook(b,editing=false){if(!validBook(b))throw Error(L_vocabulary_store_js.t("단어장 이름(1–80자)과 아이콘을 확인하세요."));return transaction(['books'],'readwrite',(t,set,fail)=>{const s=t.objectStore('books'),q=s.get(b.id);q.onsuccess=()=>{if(editing&&!q.result){fail(L_vocabulary_store_js.t("다른 창에서 삭제된 단어장입니다. 목록을 다시 열어 주세요."));return}const row={id:b.id,name:b.name.trim(),icon:b.icon,createdAt:q.result?.createdAt||Date.now(),updatedAt:Date.now()};s.put(row);set(row)}})}
 async function ensureDefault(){return transaction(['books'],'readwrite',(t,set)=>{const s=t.objectStore('books'),q=s.getAll();q.onsuccess=()=>{if(q.result.length){set(q.result[0]);return}const b={id:'default',name:L_vocabulary_store_js.t("내 단어장"),icon:'📘',createdAt:Date.now(),updatedAt:Date.now()};s.put(b);set(b)}})}
 async function saveEntry(r,editing=false){if(!valid(r))throw Error(L_vocabulary_store_js.t("단어(1–500자), 뜻(1–12,000자), 언어를 확인하세요."));return transaction(['books','entries'],'readwrite',(t,set,fail)=>{const q=t.objectStore('books').get(r.notebook);q.onsuccess=()=>{if(!q.result){fail(L_vocabulary_store_js.t("선택한 단어장이 없습니다. 다른 단어장을 선택하세요."));return}const s=t.objectStore('entries'),get=s.get(r.id);get.onsuccess=()=>{if(editing&&!get.result){fail(L_vocabulary_store_js.t("이 항목이 다른 창에서 삭제되었습니다. 목록을 다시 열어 주세요."));return}if(editing&&r.expectedUpdatedAt!==undefined&&get.result.updatedAt!==r.expectedUpdatedAt){fail(L_vocabulary_store_js.t("다른 창에서 수정된 항목입니다. 다시 열고 편집하세요."));return}const row={...r,word:r.word.trim(),reading:r.reading.trim(),meaning:r.meaning.trim(),createdAt:get.result?.createdAt||Date.now(),updatedAt:Date.now()};delete row.expectedUpdatedAt;row.dedupe=dedupe(row);s.put(row);set(row)}}})}
 const removeEntry=id=>transaction(['entries'],'readwrite',t=>t.objectStore('entries').delete(id));
 const removeBook=id=>transaction(['books','entries'],'readwrite',t=>{t.objectStore('books').delete(id);const r=t.objectStore('entries').index('notebook').openCursor(IDBKeyRange.only(id));r.onsuccess=()=>{const c=r.result;if(c){c.delete();c.continue()}}});
 root.VocabularyStore={icons,languages,normalize,dedupe,valid,validBook,books,entries,saveBook,ensureDefault,saveEntry,removeEntry,removeBook};
})(globalThis);
